const $=s=>document.querySelector(s);
const ICONS={arrow:'M19 12H5m7-7-7 7 7 7',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',bulb:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',mountain:'m2 20 7-15 5 10 3-6 5 11H2m4-8 3 2 2-2',wrench:'m14 6 4 4 4-4a7 7 0 0 1-9 9L6 22l-4-4 7-7a7 7 0 0 1 9-9l-4 4Z',building:'M5 22V2h14v20M2 22h20M9 6h1m4 0h1M9 10h1m4 0h1M9 14h1m4 0h1M10 22v-4h4v4',school:'m2 9 10-7 10 7M4 8v14h16V8M9 22v-7h6v7M9 10h6',tree:'m12 2-6 8h3l-5 7h6v5h4v-5h6l-5-7h3L12 2Z',home:'m2 11 10-9 10 9M5 9v13h14V9M10 22v-7h4v7',warehouse:'M2 22V8l10-6 10 6v14M7 22V11h10v11M7 15h10M7 19h10',check:'m5 12 4 4L20 5',map:'m9 3 6 3 7-3v17l-7 3-6-3-7 3V6l7-3Zm0 0v17m6-14v17'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.search}"/></svg>`}
const STORAGE='seglab-cidade-v1';
function loadProgress(){try{const v=JSON.parse(localStorage.getItem(STORAGE));const clean={};for(const s of SECTORS)clean[s.id]=Array.isArray(v?.[s.id])?[...new Set(v[s.id].filter(id=>s.risks.some(r=>r.id===id)))]:[];return clean}catch{return Object.fromEntries(SECTORS.map(s=>[s.id,[]]))}}
let progress=loadProgress(),current=null,expanded=null,zoom=1,hintIndex=0,keyboardMode=false,cursor={x:.5,y:.5},toastTimer;
const total=SECTORS.reduce((n,s)=>n+s.risks.length,0);
const found=s=>progress[s.id]||[];
const totalFound=()=>SECTORS.reduce((n,s)=>n+found(s).length,0);
const completed=()=>SECTORS.filter(s=>found(s).length===s.risks.length).length;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(progress))}catch{toast('O progresso fica nesta sessão: o armazenamento do navegador está indisponível.')}}
function toast(msg,success=false){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').className='toast show'+(success?' success':'');toastTimer=setTimeout(()=>$('#toast').className='toast',3300)}
function openModal(content){$('#modalBody').innerHTML=content;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('#closeModal').onclick=closeModal;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
$('#helpBtn').onclick=()=>openModal(`<p class="eyebrow">SEU OLHAR FAZ A DIFERENÇA</p><h2>Como jogar</h2><ol><li>Escolha um dos sete setores no mapa.</li><li>Observe a ilustração e clique ou toque diretamente em um risco.</li><li>Ao acertar, o risco recebe um círculo. Leia a explicação, a prevenção e as referências na ficha de descoberta.</li><li>A primeira dica dá uma pista. Peça novamente para sinalizar o local. Amplie a imagem para examinar os detalhes.</li><li>Encontre todos os riscos e volte ao mapa para explorar outro setor.</li></ol><p>Não há cronômetro nem penalidade por tentativa. O progresso é salvo neste navegador.</p><p class="dialog-note">Teclado: ative “Explorar com teclado” no cenário. Use as setas para mover a mira (Shift para passos menores) e Enter para verificar a posição. Escape encerra a exploração.</p><div class="dialog-actions"><button class="button primary" onclick="closeModal()">Vamos jogar ${icon('arrow')}</button></div>`);
$('#refsBtn').onclick=()=>openModal(`<p class="eyebrow">CONTEÚDO EDUCATIVO</p><h2>Referências de prevenção</h2><p>Cada descoberta apresenta orientações e links para as fontes oficiais consultadas em outubro de 2026.</p><p>As NRs orientam a segurança ocupacional. Em casa e no lazer, o jogo utiliza orientações oficiais de prevenção, sem apresentar uma NR trabalhista como obrigação doméstica.</p><p>Para playgrounds, a referência é a série ABNT NBR 16071, com fonte do Inmetro. A recomendação de capacete ao ciclista não é apresentada como obrigação federal geral para bicicletas convencionais.</p><p class="dialog-note">A ilustração é uma situação didática. A seleção de EPIs e as medidas reais dependem da atividade, da avaliação de riscos e das regras aplicáveis. O jogo não substitui treinamento ou análise técnica.</p>`);
function resetGame(){openModal(`<p class="eyebrow">NOVO JOGADOR</p><h2>Começar de novo?</h2><p>Isso apaga as ${totalFound()} descobertas e as dicas desta partida neste navegador. Todos os setores voltarão ao início.</p><div class="dialog-actions"><button class="button" onclick="closeModal()">Continuar partida</button><button class="button primary" id="confirmReset">Sim, reiniciar</button></div>`);$('#confirmReset').onclick=()=>{progress=Object.fromEntries(SECTORS.map(s=>[s.id,[]]));save();closeModal();location.hash='mapa';renderMap();toast('Tudo pronto para um novo jogador.',true)}}
let hintTarget=null,hintLevel=0,hintText='',revealId=null,hintTimer=null,selectedRisk=null;
function fullscreen(){if(!document.fullscreenElement){const p=document.documentElement.requestFullscreen?.();p?.catch(()=>toast('Use F11 para abrir o navegador em tela cheia.'))}else document.exitFullscreen?.()}
function hudBrand(){return `<a href="#mapa" class="hud-brand" aria-label="Seg Lab, voltar ao mapa"><span class="brand-mark">S<span>+</span></span><span>SEG<b>LAB</b><small>MISSÃO PREVENÇÃO</small></span></a>`}
function hudTools(){return `<div class="hud-tools">${current?'<button class="hud-icon" id="hudPanel" title="Ocultar painel de descobertas" aria-label="Ocultar painel de descobertas" aria-expanded="true" aria-controls="sceneSide">▤</button>':''}<button class="hud-icon" id="fullBtn" title="Tela cheia" aria-label="Tela cheia">⛶</button><button class="hud-icon" id="hudHelp" title="Como jogar" aria-label="Como jogar">?</button><button class="hud-icon" id="hudReset" title="Reiniciar jogo" aria-label="Reiniciar jogo">${icon('reset')}</button></div>`}
function bindHud(){if(current){let panelVisible=true;$('#hudPanel').onclick=()=>{panelVisible=!panelVisible;$('#sceneSide').style.display=panelVisible?'block':'none';$('#hudPanel').setAttribute('aria-expanded',String(panelVisible));$('#hudPanel').setAttribute('aria-label',panelVisible?'Ocultar painel de descobertas':'Mostrar painel de descobertas');$('#hudPanel').title=panelVisible?'Ocultar painel de descobertas':'Mostrar painel de descobertas'}}window.SegLabAudio?.mountControl();document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>location.hash=b.dataset.sector);$('#fullBtn').onclick=fullscreen;$('#hudHelp').onclick=()=>$('#helpBtn').click();$('#hudReset').onclick=resetGame}
function renderMap(){window.SegLabAudio?.setScene('mapa');clearTimeout(hintTimer);current=null;selectedRisk=null;document.title='Seg Lab — Cidade da prevenção';const n=totalFound();$('#app').innerHTML=`<div class="game-world map-world"><div class="world-viewport" id="worldViewport"><div class="world-art" id="worldArt"><img src="assets/cidade-seglab.png" alt="Mapa ilustrado da cidade Seg Lab, com praça, prédios corporativos, mina, escola, armazém, casas e oficina." draggable="false">${SECTORS.map((s,i)=>`<button class="world-pin ${found(s).length===s.risks.length?'done':''}" style="left:${s.map[0]}%;top:${s.map[1]}%" data-sector="${s.id}" aria-label="Explorar ${s.name}, ${found(s).length} de ${s.risks.length} riscos encontrados"><span class="pin-badge">${found(s).length===s.risks.length?icon('check'):icon(s.icon)}</span><span class="pin-copy"><b>${s.short}</b><small>${found(s).length} / ${s.risks.length} riscos</small></span><span class="pin-go">↗</span></button>`).join('')}</div></div><div class="world-vignette"></div><header class="hud-top">${hudBrand()}<div class="hud-global"><span class="hud-mini">SUA JORNADA</span><strong>${n}<i> / ${total}</i></strong><div class="hud-progress"><i style="width:${n/total*100}%"></i></div><small>${completed()} de 7 setores concluídos</small></div>${hudTools()}</header><section class="hud-objective"><span class="hud-kicker">${n===total?'MISSÃO CUMPRIDA':'MAPA DA CIDADE'}</span><h1>${n===total?'Um olhar que transforma.':'Explore a cidade.'}</h1><p>${n===total?'Você identificou os '+total+' riscos. A cidade está mais segura.':'Encontre os riscos. Complete sua missão.'}</p>${n===total?'<button class="button lime" id="playAgain">Jogar novamente</button>':''}</section><div class="hud-bottom"><div class="hud-chip">${icon('map')} <span>7 destinos <i>·</i> ${total} riscos</span></div><div class="map-instruction">${icon('search')} <span>Selecione um local para explorar</span></div><button class="hud-chip" id="sectorMenu" aria-expanded="false">${icon('building')} <span>Setores</span><b>⌃</b></button></div><div class="hud-sector-menu" id="sectorMenuPanel" hidden>${SECTORS.map(s=>`<button data-sector="${s.id}">${icon(s.icon)}<span>${s.name}</span><small>${found(s).length}/${s.risks.length}</small></button>`).join('')}</div></div>`;bindHud();$('#sectorMenu').onclick=()=>{const panel=$('#sectorMenuPanel');panel.hidden=!panel.hidden;$('#sectorMenu').setAttribute('aria-expanded',String(!panel.hidden))};if($('#playAgain'))$('#playAgain').onclick=resetGame;requestAnimationFrame(()=>{const vp=$('#worldViewport');if(vp)vp.scrollLeft=(vp.scrollWidth-vp.clientWidth)/2})}
function renderScene(s){window.SegLabAudio?.setScene(s.id);clearTimeout(hintTimer);current=s;zoom=1;hintIndex=0;hintLevel=0;hintTarget=null;hintText='';revealId=null;selectedRisk=null;keyboardMode=false;cursor={x:.5,y:.5};expanded=null;document.title=s.name+' — Seg Lab';$('#app').innerHTML=`<div class="game-world scene-world"><div class="scene-canvas"><div class="image-viewport" id="viewport"><div class="image-stage" id="stage" tabindex="0" role="group" aria-label="Cenário ${s.name}. Clique nos riscos ou ative a exploração com teclado."><img src="assets/${s.id}.png" alt="Ilustração de ${s.name}, com ${s.risks.length} riscos para encontrar." draggable="false"><svg class="marks" id="marks" viewBox="0 0 1536 1024" preserveAspectRatio="none" aria-hidden="true"></svg></div></div></div><div class="world-vignette scene-vignette"></div><header class="hud-top"><div class="hud-scene-heading"><button class="hud-icon" id="backMap" aria-label="Voltar ao mapa" title="Voltar ao mapa">${icon('arrow')}</button><div><span class="hud-mini">EXPLORAR SETOR</span><h1>${s.name}</h1></div></div><div class="hud-global scene-global"><span class="hud-mini">RISCOS IDENTIFICADOS</span><strong id="sceneCount"></strong><div class="hud-progress"><i id="sceneProgress"></i></div></div>${hudTools()}</header><aside class="scene-side" id="sceneSide"></aside><div class="hud-bottom scene-bottom"><div class="zoom-controls hud-chip"><button id="zoomOut" aria-label="Diminuir imagem">−</button><span id="zoomLabel">100%</span><button id="zoomIn" aria-label="Ampliar imagem">+</button><button id="zoomFit">Ajustar</button></div><button class="hud-chip keyboard-control" id="keyboardBtn" title="Explorar com teclado">${icon('search')}<span>Teclado</span></button><button class="hud-hint" id="hintBtn">${icon('bulb')}<span id="hintLabel">Pedir uma dica</span><span class="keycap">D</span></button></div><div class="game-hint" id="hintArea" aria-live="polite" hidden></div><div class="scene-key-help" id="exploreHelp" hidden>Setas: mover · Shift: precisão · Enter: verificar · Esc: sair</div></div>`;bindHud();$('#backMap').onclick=()=>location.hash='mapa';$('#zoomIn').onclick=()=>setZoom(zoom+.5);$('#zoomOut').onclick=()=>setZoom(zoom-.5);$('#zoomFit').onclick=()=>setZoom(1);$('#stage').onclick=e=>{const b=e.currentTarget.getBoundingClientRect();inspect((e.clientX-b.left)/b.width,(e.clientY-b.top)/b.height)};$('#stage img').onload=fitScene;$('#keyboardBtn').onclick=()=>{keyboardMode=!keyboardMode;$('#stage').focus();$('#exploreHelp').hidden=!keyboardMode;drawMarks()};$('#stage').onkeydown=e=>{if(!keyboardMode)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter','Escape'].includes(e.key))e.preventDefault();const step=e.shiftKey?.005:.025;if(e.key==='ArrowLeft')cursor.x=Math.max(0,cursor.x-step);if(e.key==='ArrowRight')cursor.x=Math.min(1,cursor.x+step);if(e.key==='ArrowUp')cursor.y=Math.max(0,cursor.y-step);if(e.key==='ArrowDown')cursor.y=Math.min(1,cursor.y+step);if(e.key==='Enter')inspect(cursor.x,cursor.y);if(e.key==='Escape'){$('#keyboardBtn').click();return}drawMarks()};$('#hintBtn').onclick=requestHint;updateSide();drawMarks();requestAnimationFrame(fitScene)}
function fitScene(){if(!current)return;const vp=$('#viewport'),stage=$('#stage');if(!vp||!stage)return;const w=Math.min(vp.clientWidth,vp.clientHeight*1.5);stage.style.width=Math.max(1,w)*zoom+'px';$('#zoomLabel').textContent=Math.round(zoom*100)+'%';$('#zoomOut').disabled=zoom===1;$('#zoomIn').disabled=zoom===3}
function setZoom(n){const vp=$('#viewport');const oldWidth=$('#stage').getBoundingClientRect?.().width||vp.clientWidth;zoom=Math.max(1,Math.min(3,n));fitScene();if(hintLevel>=2&&hintTarget)centerRisk(hintTarget)}
function centerRisk(r){const vp=$('#viewport'),stage=$('#stage');requestAnimationFrame(()=>{vp.scrollLeft=r.area[0]*stage.offsetWidth-vp.clientWidth/2;vp.scrollTop=r.area[1]*stage.offsetHeight-vp.clientHeight/2})}
function requestHint(){if(!current)return;const missing=current.risks.filter(r=>!found(current).includes(r.id));if(!missing.length)return;if(!hintTarget||found(current).includes(hintTarget.id)){hintTarget=missing[0];hintLevel=0}hintLevel++;window.SegLabAudio?.cue('hint');hintText=hintLevel===1?hintTarget.hint:'Procure dentro do círculo pulsante. Clique no risco para identificá-lo.';if(hintLevel>=2){revealId=hintTarget.id;clearTimeout(hintTimer);hintTimer=setTimeout(()=>{revealId=null;drawMarks()},12000);centerRisk(hintTarget)}updateHint();drawMarks()}
function updateHint(){const box=$('#hintArea');if(!box)return;box.hidden=!hintText;if(hintText)box.innerHTML=`<span class="hint-emblem">${icon('bulb')}</span><div><strong>${hintLevel===1?'DICA 1 · OBSERVE O AMBIENTE':'DICA 2 · LOCAL SINALIZADO'}</strong><p>${hintText}</p></div><button class="hint-close" aria-label="Fechar dica">×</button>`;if(box.querySelector)box.querySelector('button')?.addEventListener('click',()=>{box.hidden=true});$('#hintLabel').textContent=hintLevel===1?'Sinalizar local':'Pedir uma dica'}
function inspect(x,y){if(!current)return;const candidates=current.risks.map(r=>({r,d:((x-r.area[0])/r.area[2])**2+((y-r.area[1])/r.area[3])**2})).filter(o=>o.d<=1).sort((a,b)=>a.d-b.d);if(!candidates.length){toast('Observe mais um pouco. Use uma dica se precisar.');return}const r=candidates[0].r;selectedRisk=r.id;expanded=r.id;if(found(current).includes(r.id)){updateSide();toast('Risco já identificado. Reveja o cuidado necessário.');return}progress[current.id].push(r.id);window.SegLabAudio?.cue('success');if(hintTarget?.id===r.id){hintTarget=null;hintLevel=0;hintText='';revealId=null;clearTimeout(hintTimer);updateHint()}save();drawMarks();updateSide();toast('Risco identificado! '+r.title+'.',true)}
function drawMarks(){if(!current)return;$('#marks').innerHTML=current.risks.filter(r=>found(current).includes(r.id)).map(r=>{const [x,y,rx,ry]=r.area;const number=found(current).indexOf(r.id)+1;return `<g><ellipse class="found-mark" cx="${x*1536}" cy="${y*1024}" rx="${rx*1536}" ry="${ry*1024}"/><circle class="mark-label" cx="${(x+rx*.7)*1536}" cy="${(y-ry*.7)*1024}" r="17"/><text class="mark-text" x="${(x+rx*.7)*1536}" y="${(y-ry*.7)*1024}">${number}</text></g>`}).join('')+(revealId?(()=>{const r=current.risks.find(r=>r.id===revealId);if(!r)return '';const[x,y,rx,ry]=r.area;return `<g class="hint-target"><ellipse class="hint-halo" cx="${x*1536}" cy="${y*1024}" rx="${rx*1536+10}" ry="${ry*1024+10}"/><ellipse class="hint-ring" cx="${x*1536}" cy="${y*1024}" rx="${rx*1536+10}" ry="${ry*1024+10}"/><path class="hint-cross" d="M${x*1536-8} ${y*1024}h16M${x*1536} ${y*1024-8}v16"/></g>`})():'')+(keyboardMode?`<g class="keyboard-dot"><circle cx="${cursor.x*1536}" cy="${cursor.y*1024}" r="12"/><path d="M${cursor.x*1536-20} ${cursor.y*1024}h40M${cursor.x*1536} ${cursor.y*1024-20}v40"/></g>`:'')}
function updateSide(){const s=current,n=found(s).length,done=n===s.risks.length;$('#sceneCount').innerHTML=`${n}<i> / ${s.risks.length}</i>`;$('#sceneProgress').style.width=n/s.risks.length*100+'%';const discovered=found(s).map(id=>s.risks.find(r=>r.id===id));const r=s.risks.find(r=>r.id===selectedRisk);$('#sceneSide').innerHTML=`<div class="hud-discoveries"><span class="hud-mini">SUAS DESCOBERTAS</span><div class="discovery-slots">${discovered.map((r,i)=>`<button class="discovery found ${selectedRisk===r.id?'active':''}" data-risk="${r.id}" title="${r.title}" aria-label="Rever ${r.title}">${icon('check')}<small>${i+1}</small></button>`).join('')}${Array.from({length:s.risks.length-n},(_,i)=>`<span class="discovery unknown" aria-label="Risco ainda não identificado">${n+i+1}</span>`).join('')}</div><small class="discovery-caption">${done?'Todos os riscos identificados!':'Encontre todos neste cenário.'}</small></div>${r?`<article class="risk-dossier"><div class="dossier-heading"><span class="hud-kicker">RISCO IDENTIFICADO</span><button id="closeDossier" class="hint-close" aria-label="Fechar ficha">×</button></div><h2>${r.title}</h2><p>${r.description}</p><h3>COMO PREVENIR</h3><p>${r.prevention}</p><h3>REFERÊNCIA DE PREVENÇÃO</h3><div class="refs">${r.refs.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div>${r.note?`<details><summary>Sobre esta referência</summary><p>${r.note}</p></details>`:''}</article>`:''}${done?`<section class="complete-panel"><span class="hud-kicker">SETOR CONCLUÍDO</span><h3>Boa missão!</h3><p>${totalFound()===total?'Você completou os sete setores da cidade!':'Mais um ambiente, mais cuidado. Explore o próximo setor.'}</p><button class="button lime" id="completeMap">${icon('map')} Voltar ao mapa</button></section>`:''}`;document.querySelectorAll('[data-risk]').forEach(b=>b.onclick=()=>{selectedRisk=b.dataset.risk;updateSide()});if($('#closeDossier'))$('#closeDossier').onclick=()=>{selectedRisk=null;updateSide()};if($('#completeMap'))$('#completeMap').onclick=()=>location.hash='mapa';$('#hintBtn').disabled=done;updateHint()}
window.addEventListener('resize',()=>{if(current)fitScene()});
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='d'&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&current&&!document.querySelector('dialog[open]')&&!document.querySelector('#introOverlay')&&!keyboardMode){e.preventDefault();requestHint()}});
function route(){const id=location.hash.slice(1);const s=SECTORS.find(s=>s.id===id);if(s)renderScene(s);else renderMap()}
window.addEventListener('hashchange',route);route();
